package jsonquery

import (
	"context"
	"encoding/json"
	"strings"
	"testing"
)

// Independent ROUND3 observations from official JSONata 2.2.2. Keep reference
// results and approved stronger-profile rejections separate. Every expression
// executes only through the existing production private worker.
func TestMatcherProjectionReviewReference(t *testing.T) {
	supported(t)
	var cases []struct {
		fixture
		Category       string `json:"category"`
		Classification string `json:"classification"`
		Want           string `json:"want"`
	}
	if err := json.Unmarshal([]byte(matcherProjectionReviewJSON), &cases); err != nil {
		t.Fatal(err)
	}
	if len(cases) != 130 {
		t.Fatal("ROUND3 coverage changed")
	}
	for _, f := range cases {
		if f.Classification == "reference" {
			if f.Want != f.Reference.State {
				t.Fatal("reference expectation changed")
			}
		} else if f.Classification != "safe-profile" || f.Want != "down" || f.Reference.State != "up" {
			t.Fatal("unclassified profile expectation")
		}
		t.Run(f.Category+"/"+f.Name, func(t *testing.T) {
			r := request(f.Expression, string(f.Expected))
			r.Document, r.Query.Operator = f.Document, f.Operator
			if err := r.Validate(); err != nil {
				t.Fatal(err)
			}
			got := Check(context.Background(), r)
			t.Logf("observed=%s want=%s", got.State, f.Want)
			if got.State != f.Want || got.LatencyMs <= 0 || strings.Contains(got.Message, "private-marker") {
				t.Fatalf("state=%s want=%s message=%q latency=%g", got.State, f.Want, got.Message, got.LatencyMs)
			}
			if f.Want == "down" && got.Message != "service check failed" {
				t.Fatalf("expected fixed bounded failure: %+v", got)
			}
		})
	}
}

